// Copies public/engine.js (the single source of the app's data and logic)
// into a CommonJS module the Ask function can import. Runs on every Netlify build.
import { readFileSync, writeFileSync } from "node:fs";

const src = readFileSync(new URL("../public/engine.js", import.meta.url), "utf8");
const out =
  "/* GENERATED by scripts/sync-engine.mjs from public/engine.js. Do not edit; edit public/engine.js. */\n" +
  src +
  "\nmodule.exports = { ASK_RULES, askTools, askContext, LOCATIONS, months, monthById };\n";
writeFileSync(new URL("../netlify/functions/_engine.cjs", import.meta.url), out);
console.log("Synced engine.js -> netlify/functions/_engine.cjs");
